CREATE TABLE IF NOT EXISTS "MenuItem" ("id" TEXT NOT NULL PRIMARY KEY, "ownerId" TEXT NOT NULL, "category" TEXT NOT NULL DEFAULT 'HAND', "name" TEXT NOT NULL, "description" TEXT, "technique" TEXT, "priceFrom" REAL NOT NULL, "priceTo" REAL, "minutes" INTEGER, "durabilityWeeks" INTEGER, "difficulty" INTEGER, "occasion" TEXT, "images" TEXT NOT NULL DEFAULT '[]', "materials" TEXT NOT NULL DEFAULT '[]', "sourceDesignId" TEXT, "sortOrder" INTEGER NOT NULL DEFAULT 0, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "MenuItem_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "MenuItem_ownerId_sortOrder_idx" ON "MenuItem"("ownerId", "sortOrder");
